'use client'

import { useSession } from 'next-auth/react'
import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import AppLayout from '@/components/AppLayout'

interface AIPreference {
  model: 'gpt-4' | 'gpt-3.5' | 'claude' | 'custom'
  temperature: number
  maxTokens: number
  responseStyle: 'concise' | 'detailed' | 'balanced'
  focusAreas: string[]
}

export default function AIPage() {
  const { data: session, status } = useSession()
  const router = useRouter()
  const [prompt, setPrompt] = useState('')
  const [response, setResponse] = useState('')
  const [loading, setLoading] = useState(false)
  const [preferences, setPreferences] = useState<AIPreference>({
    model: 'gpt-4',
    temperature: 0.7,
    maxTokens: 1000,
    responseStyle: 'balanced',
    focusAreas: []
  })
  const [showSettings, setShowSettings] = useState(false)

  useEffect(() => {
    if (status === 'unauthenticated') {
      router.push('/auth/signin')
    }
  }, [status, router])

  // Load saved preferences
  useEffect(() => {
    const saved = localStorage.getItem('ai-preferences')
    if (saved) {
      try {
        setPreferences(JSON.parse(saved))
      } catch (e) {
        console.error('Failed to load preferences')
      }
    }
  }, [])

  // Save preferences
  const savePreferences = (newPrefs: AIPreference) => {
    setPreferences(newPrefs)
    localStorage.setItem('ai-preferences', JSON.stringify(newPrefs))
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!prompt.trim()) return

    setLoading(true)
    setResponse('')

    try {
      // Use the general AI chat endpoint
      const res = await fetch('/api/ai/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          message: prompt,
          model: preferences.model === 'custom' ? 'gpt-4' : preferences.model,
          temperature: preferences.temperature,
          maxTokens: preferences.maxTokens,
        }),
      })

      if (!res.ok) {
        const error = await res.json().catch(() => ({ error: 'Failed to get AI response' }))
        throw new Error(error.error || 'AI service error')
      }

      const data = await res.json()

      console.log('AI API Response:', data) // Debug log

      if (data.response) {
        setResponse(data.response)
      } else if (data.error) {
        setResponse(`Error: ${data.error}\n\nNote: If you haven't set OPENAI_API_KEY, the system will use mock responses for development.`)
      } else {
        setResponse('AI response received but in unexpected format. Response data: ' + JSON.stringify(data))
      }
    } catch (error: any) {
      console.error('AI request error:', error)
      setResponse(`Error: ${error.message || 'Failed to get AI response. Please try again.'}\n\nNote: If you haven't set OPENAI_API_KEY, the system will use mock responses for development.\n\nCheck the browser console for more details.`)
    } finally {
      setLoading(false)
    }
  }

  if (status === 'loading') {
    return (
      <AppLayout>
        <div className="flex items-center justify-center h-screen">
          <div className="text-gray-500">Loading...</div>
        </div>
      </AppLayout>
    )
  }
  if (!session) return null

  return (
    <AppLayout>
      <div className="p-8">
        <div className="max-w-4xl mx-auto">
          <div className="mb-8">
            <div className="flex items-center justify-between mb-2">
              <h1 className="text-3xl font-bold text-gray-900">AI Assistant</h1>
              <button
                onClick={() => setShowSettings(!showSettings)}
                className="flex items-center space-x-2 px-4 py-2 text-sm text-gray-600 hover:text-gray-900 border border-gray-300 rounded-lg"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                </svg>
                <span>Configure AI</span>
              </button>
            </div>
            <p className="text-gray-600">Get AI-powered insights tailored to your preferences.</p>
          </div>

          {/* Settings Panel */}
          {showSettings && (
            <div className="bg-white rounded-lg shadow-sm p-6 border border-gray-200 mb-6">
              <h3 className="text-lg font-semibold text-gray-900 mb-4">AI Configuration</h3>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">AI Model</label>
                  <select
                    value={preferences.model}
                    onChange={(e) => savePreferences({ ...preferences, model: e.target.value as any })}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="gpt-4">GPT-4 (Recommended)</option>
                    <option value="gpt-3.5">GPT-3.5 Turbo</option>
                    <option value="claude">Claude (Anthropic)</option>
                    <option value="custom">Custom Model</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Temperature: {preferences.temperature}
                  </label>
                  <input
                    type="range"
                    min="0"
                    max="1"
                    step="0.1"
                    value={preferences.temperature}
                    onChange={(e) => savePreferences({ ...preferences, temperature: parseFloat(e.target.value) })}
                    className="w-full"
                  />
                  <div className="flex justify-between text-xs text-gray-500 mt-1">
                    <span>Focused</span>
                    <span>Creative</span>
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Response Style</label>
                  <select
                    value={preferences.responseStyle}
                    onChange={(e) => savePreferences({ ...preferences, responseStyle: e.target.value as any })}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="concise">Concise</option>
                    <option value="balanced">Balanced</option>
                    <option value="detailed">Detailed</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Max Tokens</label>
                  <input
                    type="number"
                    min="100"
                    max="4000"
                    step="100"
                    value={preferences.maxTokens}
                    onChange={(e) => savePreferences({ ...preferences, maxTokens: parseInt(e.target.value) })}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  />
                </div>
              </div>
            </div>
          )}

          {/* AI Chat Interface */}
          <div className="bg-white rounded-lg shadow-sm p-6 border border-gray-200 mb-6">
            <div className="flex items-center space-x-3 mb-4">
              <div className="w-12 h-12 bg-gradient-to-br from-purple-500 to-blue-500 rounded-lg flex items-center justify-center">
                <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
                </svg>
              </div>
              <div>
                <h2 className="text-xl font-semibold text-gray-900">AI-Powered Analysis</h2>
                <p className="text-sm text-gray-500">Using {preferences.model} ΓÇó {preferences.responseStyle} responses</p>
              </div>
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  What would you like help with?
                </label>
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  placeholder="E.g., 'Review my solution to the Two Sum problem' or 'Help me brainstorm solutions for reducing food waste'"
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  rows={4}
                />
              </div>
              <button
                type="submit"
                disabled={loading || !prompt.trim()}
                className="w-full bg-gradient-to-r from-purple-600 to-blue-600 text-white py-3 px-6 rounded-lg font-semibold hover:from-purple-700 hover:to-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition"
              >
                {loading ? 'Analyzing...' : 'Get AI Insights'}
              </button>
            </form>
          </div>

          {response && (
            <div className="bg-white rounded-lg shadow-sm p-6 border border-gray-200">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold text-gray-900">AI Response</h3>
                {!process.env.NEXT_PUBLIC_OPENAI_API_KEY && (
                  <span className="text-xs text-gray-500 bg-yellow-50 px-2 py-1 rounded">
                    Using Mock Service (Set OPENAI_API_KEY for real AI)
                  </span>
                )}
              </div>
              <div className="prose max-w-none">
                <div className="whitespace-pre-wrap text-gray-700 font-sans bg-gray-50 p-4 rounded-lg">{response}</div>
              </div>
            </div>
          )}

          {/* Feature Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mt-8">
            <div className="bg-white rounded-lg shadow-sm p-6 border border-gray-200">
              <div className="w-10 h-10 rounded-lg bg-blue-100 flex items-center justify-center mb-4">
                <svg className="w-6 h-6 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
              </div>
              <h3 className="font-semibold mb-2">Code Review</h3>
              <p className="text-sm text-gray-600">Get detailed feedback on your code solutions and optimizations</p>
            </div>

            <div className="bg-white rounded-lg shadow-sm p-6 border border-gray-200">
              <div className="w-10 h-10 rounded-lg bg-purple-100 flex items-center justify-center mb-4">
                <svg className="w-6 h-6 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
                </svg>
              </div>
              <h3 className="font-semibold mb-2">Problem Analysis</h3>
              <p className="text-sm text-gray-600">Break down complex problems and explore solution approaches</p>
            </div>

            <div className="bg-white rounded-lg shadow-sm p-6 border border-gray-200">
              <div className="w-10 h-10 rounded-lg bg-green-100 flex items-center justify-center mb-4">
                <svg className="w-6 h-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                </svg>
              </div>
              <h3 className="font-semibold mb-2">Learning Path</h3>
              <p className="text-sm text-gray-600">Get personalized recommendations for skill development</p>
            </div>
          </div>
        </div>
      </div>
    </AppLayout>
  )
}

/**
 * API: General AI Chat
 * 
 * A general-purpose AI chat endpoint that uses the idea guidance module
 * for any user query. This provides a flexible interface for the AI page.
 */

import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth'
import { performSafetyCheck, sanitizeAIOutput } from '@/lib/ai/safety'
import { SYSTEM_PROMPTS } from '@/lib/ai/prompts'
import { getAIService } from '@/lib/ai/aiService'

export async function POST(req: NextRequest) {
  try {
    const session = await getAuthSession()
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { message, model, temperature, maxTokens } = await req.json()

    if (!message || !message.trim()) {
      return NextResponse.json(
        { error: 'Message is required' },
        { status: 400 }
      )
    }

    // Safety check
    const safetyCheck = await performSafetyCheck(session.user.id, message)
    if (!safetyCheck.allowed) {
      return NextResponse.json(
        { error: safetyCheck.reason || 'Safety check failed' },
        { status: 403 }
      )
    }

    // Use AI service directly for general chat
    const aiService = getAIService({
      model: model || 'gpt-4',
      temperature: temperature || 0.7,
      maxTokens: maxTokens || 1000,
    })

    // Create a general guidance prompt
    const prompt = `You are a thinking mentor helping a student. The student asks:

"${message}"

Your role is to provide GUIDANCE only. Do NOT solve problems for them. Do NOT write code. Do NOT provide complete solutions.

Instead, provide:
ΓÇó Structured guidance on how to think about the problem
ΓÇó Questions to help them explore the topic
ΓÇó Resources or approaches they might consider
ΓÇó Encouragement to think through it themselves

Be concise, supportive, and focused on helping them think better.`

    const systemPrompt = SYSTEM_PROMPTS.ideaGuidance

    const response = await aiService.call(prompt, systemPrompt)

    if (response.error) {
      return NextResponse.json(
        { error: response.error },
        { status: 500 }
      )
    }

    const sanitized = sanitizeAIOutput(response.content)

    return NextResponse.json({ 
      response: sanitized,
      model: model || 'gpt-4',
    })
  } catch (error: any) {
    console.error('AI chat error:', error)
    return NextResponse.json(
      { error: error.message || 'Internal server error' },
      { status: 500 }
    )
  }
}

/**
 * API: Coding Practice Feedback
 * 
 * Provides feedback on approach quality, NOT code correction.
 */

import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth'
import { CodingFeedbackModule } from '@/lib/ai/modules'
import { AIOrchestrator } from '@/lib/ai/orchestrator'
import { getCachedInsight, cacheInsight } from '@/lib/ai/memory'
import { sanitizeAIOutput } from '@/lib/ai/safety'

export async function POST(req: NextRequest) {
  try {
    const session = await getAuthSession()
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { submissionId, explanation, timeTaken, codeLength, challengeTitle } =
      await req.json()

    if (!submissionId) {
      return NextResponse.json(
        { error: 'Submission ID required' },
        { status: 400 }
      )
    }

    // Check cache first
    const cached = await getCachedInsight(
      session.user.id,
      'coding',
      submissionId
    )
    if (cached) {
      return NextResponse.json({ feedback: cached, cached: true })
    }

    // Initialize AI modules
    const orchestrator = new AIOrchestrator()
    const feedbackModule = new CodingFeedbackModule(orchestrator)

    // Get feedback
    const feedback = await feedbackModule.provideFeedback(
      session.user.id,
      submissionId,
      explanation,
      timeTaken,
      codeLength || 0,
      challengeTitle
    )

    if (!feedback) {
      return NextResponse.json(
        { message: 'Feedback not generated (missing explanation or below threshold)' },
        { status: 200 }
      )
    }

    // Sanitize and cache
    const sanitized = sanitizeAIOutput(feedback)
    await cacheInsight(session.user.id, 'coding', submissionId, sanitized)

    return NextResponse.json({ feedback: sanitized, cached: false })
  } catch (error: any) {
    console.error('Coding feedback error:', error)
    return NextResponse.json(
      { error: error.message || 'Internal server error' },
      { status: 500 }
    )
  }
}

/**
 * API: Idea Guidance (PRE-SUBMISSION)
 * 
 * Provides guidance on draft idea before submission.
 * Does NOT rewrite or add ideas.
 */

import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth'
import { IdeaGuidanceModule } from '@/lib/ai/modules'
import { AIOrchestrator } from '@/lib/ai/orchestrator'
import { performSafetyCheck, sanitizeAIOutput } from '@/lib/ai/safety'

export async function POST(req: NextRequest) {
  try {
    const session = await getAuthSession()
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { problemStatement, approach } = await req.json()

    if (!problemStatement || !approach) {
      return NextResponse.json(
        { error: 'Problem statement and approach required' },
        { status: 400 }
      )
    }

    // Safety check
    const safetyCheck = await performSafetyCheck(
      session.user.id,
      `${problemStatement} ${approach}`
    )

    if (!safetyCheck.allowed) {
      return NextResponse.json(
        { error: safetyCheck.reason || 'Safety check failed' },
        { status: 403 }
      )
    }

    // Initialize AI modules
    const orchestrator = new AIOrchestrator()
    const guidanceModule = new IdeaGuidanceModule(orchestrator)

    // Get guidance
    const result = await guidanceModule.provideGuidance(
      session.user.id,
      problemStatement,
      approach
    )

    // Sanitize output
    result.guidance = sanitizeAIOutput(result.guidance)

    return NextResponse.json(result)
  } catch (error: any) {
    console.error('Idea guidance error:', error)
    return NextResponse.json(
      { error: error.message || 'Internal server error' },
      { status: 500 }
    )
  }
}

/**
 * API: Idea Reflection (POST-SUBMISSION)
 * 
 * Generates reflective summary after idea is submitted.
 * Stores in ai_insights table.
 */

import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth'
import { IdeaReflectionModule } from '@/lib/ai/modules'
import { AIOrchestrator } from '@/lib/ai/orchestrator'
import { getCachedInsight, cacheInsight } from '@/lib/ai/memory'
import { sanitizeAIOutput } from '@/lib/ai/safety'

export async function POST(req: NextRequest) {
  try {
    const session = await getAuthSession()
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    const { ideaId, problemStatement, approach } = await req.json()

    if (!ideaId || !problemStatement || !approach) {
      return NextResponse.json(
        { error: 'Idea ID, problem statement, and approach required' },
        { status: 400 }
      )
    }

    // Check cache first
    const cached = await getCachedInsight(session.user.id, 'idea', ideaId)
    if (cached) {
      return NextResponse.json({ reflection: cached, cached: true })
    }

    // Initialize AI modules
    const orchestrator = new AIOrchestrator()
    const reflectionModule = new IdeaReflectionModule(orchestrator)

    // Generate reflection
    const reflection = await reflectionModule.generateReflection(
      session.user.id,
      ideaId,
      problemStatement,
      approach
    )

    if (!reflection) {
      return NextResponse.json(
        { message: 'Reflection not generated (quality threshold not met)' },
        { status: 200 }
      )
    }

    // Sanitize and cache
    const sanitized = sanitizeAIOutput(reflection)
    await cacheInsight(session.user.id, 'idea', ideaId, sanitized)

    return NextResponse.json({ reflection: sanitized, cached: false })
  } catch (error: any) {
    console.error('Idea reflection error:', error)
    return NextResponse.json(
      { error: error.message || 'Internal server error' },
      { status: 500 }
    )
  }
}

/**
 * API: Weekly Growth Reflection
 * 
 * Generates weekly growth narrative based on activity patterns.
 * Runs once per week per user.
 */

import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth'
import { WeeklyGrowthModule } from '@/lib/ai/modules'
import { AIOrchestrator } from '@/lib/ai/orchestrator'
import { prisma } from '@/lib/prisma'
import { shouldTriggerWeeklyReflection } from '@/lib/ai/ruleEngine'
import { sanitizeAIOutput } from '@/lib/ai/safety'

export async function POST(req: NextRequest) {
  try {
    const session = await getAuthSession()
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
    }

    // Check if weekly reflection should be triggered
    const lastWeeklyInsight = await prisma.aiInsight.findFirst({
      where: {
        userId: session.user.id,
        relatedType: 'weekly',
      },
      orderBy: {
        createdAt: 'desc',
      },
    })

    // Get activity count for last 7 days
    const sevenDaysAgo = new Date()
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7)

    const activityCount = await prisma.activityLog.count({
      where: {
        userId: session.user.id,
        createdAt: {
          gte: sevenDaysAgo,
        },
      },
    })

    const shouldTrigger = shouldTriggerWeeklyReflection(
      lastWeeklyInsight?.createdAt || null,
      activityCount
    )

    if (!shouldTrigger) {
      return NextResponse.json(
        {
          message: 'Weekly reflection not triggered (insufficient activity or too soon)',
        },
        { status: 200 }
      )
    }

    // Initialize AI modules
    const orchestrator = new AIOrchestrator()
    const weeklyModule = new WeeklyGrowthModule(orchestrator)

    // Generate reflection
    const reflection = await weeklyModule.generateWeeklyReflection(session.user.id)

    if (!reflection) {
      return NextResponse.json(
        { message: 'Weekly reflection not generated' },
        { status: 200 }
      )
    }

    // Sanitize output
    const sanitized = sanitizeAIOutput(reflection)

    return NextResponse.json({ reflection: sanitized })
  } catch (error: any) {
    console.error('Weekly reflection error:', error)
    return NextResponse.json(
      { error: error.message || 'Internal server error' },
      { status: 500 }
    )
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { createUser } from '@/lib/auth'

export async function POST(req: NextRequest) {
  const { name, email, password, college, areaOfInterest, shortGoal } = await req.json()

  try {
    if (!email || !name || !password) {
      return NextResponse.json({ error: 'Name, email, and password required' }, { status: 400 })
    }

    const user = await createUser({
      name,
      email,
      password,
      college,
      areaOfInterest,
      shortGoal
    })

    return NextResponse.json({ user }, { status: 201 })
  } catch (error: any) {
    return NextResponse.json({ error: error.message || 'Internal server error' }, { status: 500 })
  }
}

import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth'
import { prisma } from '@/lib/prisma'

export async function GET() {
  const session = await getAuthSession()
  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const logs = await prisma.activityLog.findMany({
    where: { userId: session.user.id },
    orderBy: { createdAt: 'desc' },
    take: 50,
  })

  return NextResponse.json(logs)
}

import { NextRequest, NextResponse } from 'next/server'
import { getAuthSession } from '@/lib/auth'
import { prisma } from '@/lib/prisma'

export async function GET() {
  const session = await getAuthSession()
  if (!session?.user?.id) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const userId = session.user.id
  const [ideasCount, practiceCount] = await Promise.all([
    prisma.idea.count({ where: { userId } }),
    prisma.submission.count({ where: { userId } }),
  ])

  return NextResponse.json({
    ideasCount,
    practiceCount,
  })
}

