  if (!session) return null

  return (
    <AppLayout>
      <div className="p-8">
        <div className="max-w-3xl mx-auto">
          <div className="mb-8">
            <h1 className="text-3xl font-bold text-gray-900 mb-2">Submit an Idea</h1>
