                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Problem Statement
                </label>
                <textarea
                  placeholder="Describe the problem you're trying to solve. Why does this problem matter?"
                  value={formData.problem}
                  onChange={(e) => setFormData({ ...formData, problem: e.target.value })}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  rows={5}
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Your Approach / Thinking
                </label>
                <textarea
                  placeholder="Explain your approach, methodology, or thinking process. What makes your solution unique?"
                  value={formData.approach}
                  onChange={(e) => setFormData({ ...formData, approach: e.target.value })}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  rows={8}
                  required
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Optional: Upload Files (diagram, PPT, image)
                </label>
                <input
                  type="file"
                  onChange={(e) => setFormData({ ...formData, files: e.target.files?.[0] || null })}
                  className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  accept="image/*,.pdf,.ppt,.pptx"
                />
                <p className="mt-2 text-sm text-gray-500">Max file size: 2MB</p>
              </div>

              <button
                type="submit"
                disabled={submitting}
                className="w-full bg-blue-600 text-white py-3 px-6 rounded-lg font-semibold hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                {submitting ? 'Submitting...' : 'Submit Idea'}
              </button>
            </form>
          </div>
        </div>
      </div>
    </AppLayout>
  )
}

/**
 * AI Service Layer - LLM Wrapper Abstraction
 * 
 * Provides a clean interface for LLM calls.
 * Abstracts away the specific LLM provider.
 */

export interface AIServiceConfig {
  model?: string
  temperature?: number
  maxTokens?: number
  apiKey?: string
}

export interface AIResponse {
  content: string
  usage?: {
    promptTokens: number
    completionTokens: number
    totalTokens: number
  }
  error?: string
}

/**
 * Base AI Service Interface
 */
export abstract class BaseAIService {
  protected config: AIServiceConfig

  constructor(config: AIServiceConfig = {}) {
    this.config = {
      model: config.model || 'gpt-4',
      temperature: config.temperature ?? 0.7,
      maxTokens: config.maxTokens || 1000,
      apiKey: config.apiKey || process.env.OPENAI_API_KEY,
    }
  }

  abstract call(prompt: string, systemPrompt?: string): Promise<AIResponse>
}

/**
 * OpenAI Service Implementation
 */
export class OpenAIService extends BaseAIService {
  async call(prompt: string, systemPrompt?: string): Promise<AIResponse> {
    if (!this.config.apiKey) {
      throw new Error('OpenAI API key not configured')
    }

    try {
      const response = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.config.apiKey}`,
        },
        body: JSON.stringify({
          model: this.config.model,
          messages: [
            ...(systemPrompt ? [{ role: 'system', content: systemPrompt }] : []),
            { role: 'user', content: prompt },
          ],
          temperature: this.config.temperature,
          max_tokens: this.config.maxTokens,
        }),
      })

      if (!response.ok) {
        const error = await response.json().catch(() => ({ error: 'Unknown error' }))
        return {
          content: '',
          error: error.error?.message || 'AI service error',
        }
      }

      const data = await response.json()
      const content = data.choices?.[0]?.message?.content || ''

      return {
        content,
        usage: data.usage ? {
          promptTokens: data.usage.prompt_tokens || 0,
          completionTokens: data.usage.completion_tokens || 0,
          totalTokens: data.usage.total_tokens || 0,
        } : undefined,
      }
    } catch (error: any) {
      return {
        content: '',
        error: error.message || 'Failed to call AI service',
      }
    }
  }
}

/**
 * Mock AI Service for Development (when API key not available)
 */
export class MockAIService extends BaseAIService {
  async call(prompt: string, systemPrompt?: string): Promise<AIResponse> {
    // Simulate API delay
    await new Promise(resolve => setTimeout(resolve, 800))

    // Extract the user's actual question from the prompt
    const userQuestionMatch = prompt.match(/"([^"]+)"/)
    const userQuestion = userQuestionMatch ? userQuestionMatch[1] : prompt

    // Return contextual mock response based on user question
    if (prompt.includes('guidance') || prompt.includes('missing')) {
      return {
        content: 'ΓÇó Consider adding more context to your problem statement\nΓÇó Your approach could benefit from clearer steps\nΓÇó Think about potential edge cases',
      }
    }

    if (prompt.includes('reflection') || prompt.includes('summary')) {
      return {
        content: 'This submission shows early problem framing. The approach demonstrates structured thinking.',
      }
    }

    if (prompt.includes('coding') || prompt.includes('practice') || prompt.includes('code')) {
      return {
        content: 'Your explanation shows good problem-solving approach. Consider documenting your thought process more clearly.',
      }
    }

    if (prompt.includes('weekly') || prompt.includes('growth')) {
      return {
        content: 'This week shows consistent practice. You\'ve maintained regular submissions and demonstrated growth in problem-solving.',
      }
    }

    // Handle general project/idea questions
    if (userQuestion.toLowerCase().includes('project') || userQuestion.toLowerCase().includes('build')) {
      return {
        content: `Great! You're thinking about building a project. Here's some guidance to help you structure your thinking:

ΓÇó **Define the Problem**: What specific problem are you trying to solve? Be clear about who has this problem and why it matters.

ΓÇó **Scope Your Approach**: Break down your project into smaller, manageable components. What's the minimum viable version you could build first?

ΓÇó **Consider Your Resources**: What skills, tools, or technologies do you already have? What might you need to learn?

ΓÇó **Think About Impact**: How will you know if your project is successful? What metrics or outcomes matter?

Remember, the best projects start with clear problem definition. Take time to think through the "why" before jumping into the "how".`,
      }
    }

    // Default response for general queries
    return {
      content: `I'd be happy to help you think through "${userQuestion}". 

Here are some questions to guide your thinking:
ΓÇó What specific aspect of this are you most curious about?
ΓÇó What have you already considered or tried?
ΓÇó What would success look like for you?

To get more detailed AI responses, configure OPENAI_API_KEY in your environment. For now, I'm providing guidance to help structure your thinking process.`,
    }
  }
}

/**
 * Factory function to get AI service instance
 */
export function getAIService(config?: AIServiceConfig): BaseAIService {
  const apiKey = config?.apiKey || process.env.OPENAI_API_KEY

  if (apiKey) {
    return new OpenAIService(config)
  }

  // Fallback to mock service if no API key
  console.warn('No OpenAI API key found. Using mock AI service.')
  return new MockAIService(config)
}

/**
 * Specialized AI Modules
 * 
 * Each module handles a specific AI task:
 * 1. Idea Guidance (pre-submission)
 * 2. Idea Reflection (post-submission)
 * 3. Coding Practice Feedback
 * 4. Weekly Growth Reflection
 */

import { AIOrchestrator } from './orchestrator'
import { prisma } from '@/lib/prisma'

export class IdeaGuidanceModule {
  constructor(private orchestrator: AIOrchestrator) {}

  /**
   * Provide guidance on draft idea (before submission)
   */
  async provideGuidance(
    userId: string,
    problemStatement: string,
    approach: string
  ): Promise<{ guidance: string; shouldProceed: boolean }> {
    const decision = this.orchestrator.decideIdeaGuidance(
      problemStatement,
      approach
    )

    if (!decision.shouldCallAI) {
      return {
        guidance: 'Your idea needs more depth before submission. Consider expanding your problem statement and approach.',
        shouldProceed: false,
      }
    }

    try {
      const guidance = await this.orchestrator.executeDecision(decision)
      return {
        guidance,
        shouldProceed: true,
      }
    } catch (error: any) {
      console.error('Idea guidance error:', error)
      return {
        guidance: 'Unable to generate guidance at this time. Please review your submission manually.',
        shouldProceed: true, // Allow submission even if AI fails
      }
    }
  }
}

export class IdeaReflectionModule {
  constructor(private orchestrator: AIOrchestrator) {}

  /**
   * Generate reflection after idea submission
   */
  async generateReflection(
    userId: string,
    ideaId: string,
    problemStatement: string,
    approach: string
  ): Promise<string | null> {
    const wordCount =
      (problemStatement?.split(/\s+/).length || 0) +
      (approach?.split(/\s+/).length || 0)

    const decision = this.orchestrator.decideIdeaReflection(
      problemStatement,
      approach,
      wordCount
    )

    if (!decision.shouldCallAI) {
      return null // No reflection for low-quality submissions
    }

    try {
      const reflection = await this.orchestrator.executeDecision(decision)

      // Store insight in database
      await prisma.aiInsight.create({
        data: {
          userId,
          relatedType: 'idea',
          relatedId: ideaId,
          insightText: reflection,
        },
      })

      // Log activity
      await prisma.activityLog.create({
        data: {
          userId,
          actionType: 'ai_insight_generated',
          referenceId: ideaId,
          metadata: JSON.stringify({ type: 'idea_reflection' }),
        },
      })

      return reflection
    } catch (error: any) {
      console.error('Idea reflection error:', error)
      return null // Fail gracefully
    }
  }
}

export class CodingFeedbackModule {
  constructor(private orchestrator: AIOrchestrator) {}

  /**
   * Provide feedback on coding submission
   */
  async provideFeedback(
    userId: string,
    submissionId: string,
    explanation: string | undefined,
    timeTaken: number | undefined,
    codeLength: number,
    challengeTitle?: string
  ): Promise<string | null> {
    const decision = this.orchestrator.decideCodingFeedback(
      explanation,
      timeTaken,
      codeLength,
      challengeTitle
    )

    if (!decision.shouldCallAI) {
      return null
    }

    try {
      const feedback = await this.orchestrator.executeDecision(decision)

      // Store insight
      await prisma.aiInsight.create({
        data: {
          userId,
          relatedType: 'coding',
          relatedId: submissionId,
          insightText: feedback,
        },
      })

      // Log activity
      await prisma.activityLog.create({
        data: {
          userId,
          actionType: 'ai_insight_generated',
          referenceId: submissionId,
          metadata: JSON.stringify({ type: 'coding_feedback' }),
        },
      })

      return feedback
    } catch (error: any) {
      console.error('Coding feedback error:', error)
      return null
    }
  }
}

export class WeeklyGrowthModule {
  constructor(private orchestrator: AIOrchestrator) {}

  /**
   * Generate weekly growth reflection
   */
  async generateWeeklyReflection(userId: string): Promise<string | null> {
    // Get activity from last 7 days
    const sevenDaysAgo = new Date()
    sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7)

    const activities = await prisma.activityLog.findMany({
      where: {
        userId,
        createdAt: {
          gte: sevenDaysAgo,
        },
      },
      orderBy: {
        createdAt: 'desc',
      },
    })

    const activityCount = activities.length

    // Check for consistency
    const consistencyDetected = activityCount >= 5

    const decision = this.orchestrator.decideWeeklyGrowth(
      activityCount,
      consistencyDetected
    )

    if (!decision.shouldCallAI) {
      return null
    }

    // Build activity summary
    const activityTypes = activities.map(a => a.actionType)
    const activitySummary = `User had ${activityCount} activities: ${activityTypes.join(', ')}`

    const consistencyPattern = consistencyDetected
      ? 'Strong consistency detected with regular submissions'
      : 'Moderate activity level'

    // Get recent highlights (ideas and submissions)
    const recentIdeas = await prisma.idea.findMany({
      where: {
        userId,
        createdAt: {
          gte: sevenDaysAgo,
        },
      },
      take: 3,
      orderBy: {
        createdAt: 'desc',
      },
    })

    const recentHighlights = recentIdeas.length > 0
      ? `Recent ideas: ${recentIdeas.map(i => i.title).join(', ')}`
      : 'Continued practice and engagement'

    // Update decision context
    decision.context = {
      ...decision.context,
      activitySummary,
      consistencyPattern,
      recentHighlights,
    }

    try {
      const reflection = await this.orchestrator.executeDecision(decision)

      // Store insight
      await prisma.aiInsight.create({
        data: {
          userId,
          relatedType: 'weekly',
          relatedId: null,
          insightText: reflection,
        },
      })

      // Log activity
      await prisma.activityLog.create({
        data: {
          userId,
          actionType: 'ai_insight_generated',
          referenceId: null,
          metadata: JSON.stringify({ type: 'weekly_reflection' }),
        },
      })

      return reflection
    } catch (error: any) {
      console.error('Weekly reflection error:', error)
      return null
    }
  }
}

/**
 * AI Orchestrator - Core Decision Layer
 * 
 * Decides:
 * - Whether AI should be called
 * - Which AI module to call
 * - What context to send
 * 
 * Controls cost, safety, and quality.
 */

import { RuleEngineResult, evaluateIdea, evaluateActivity, evaluateCoding } from './ruleEngine'
import { BaseAIService, getAIService } from './aiService'
import { PROMPTS, SYSTEM_PROMPTS } from './prompts'

export interface OrchestratorContext {
  userId: string
  ruleResult: RuleEngineResult
  additionalData?: Record<string, any>
}

export interface OrchestratorDecision {
  shouldCallAI: boolean
  module?: 'ideaGuidance' | 'ideaReflection' | 'codingFeedback' | 'weeklyGrowth'
  reason?: string
  context?: any
}

/**
 * Main Orchestrator Class
 */
export class AIOrchestrator {
  private aiService: BaseAIService

  constructor(aiService?: BaseAIService) {
    this.aiService = aiService || getAIService()
  }

  /**
   * Decide whether to call AI for idea guidance (pre-submission)
   */
  decideIdeaGuidance(
    problemStatement: string,
    approach: string
  ): OrchestratorDecision {
    const ruleResult = evaluateIdea({ problemStatement, approach })

    // Rule: If idea is too short, skip AI
    if (ruleResult.flags.includes('needs_depth')) {
      return {
        shouldCallAI: false,
        reason: 'Idea too short for AI guidance',
      }
    }

    // Rule: If idea is structured enough, provide guidance
    if (ruleResult.shouldCallAI) {
      return {
        shouldCallAI: true,
        module: 'ideaGuidance',
        reason: 'Idea meets quality threshold for guidance',
        context: {
          problemStatement,
          approach,
          flags: ruleResult.flags,
        },
      }
    }

    return {
      shouldCallAI: false,
      reason: 'Idea does not meet minimum quality threshold',
    }
  }

  /**
   * Decide whether to call AI for idea reflection (post-submission)
   */
  decideIdeaReflection(
    problemStatement: string,
    approach: string,
    wordCount: number
  ): OrchestratorDecision {
    const ruleResult = evaluateIdea({
      problemStatement,
      approach,
      wordCount,
    })

    // Rule: Only reflect on ideas that meet quality threshold
    if (ruleResult.signals.qualityThreshold) {
      return {
        shouldCallAI: true,
        module: 'ideaReflection',
        reason: 'Idea meets quality threshold for reflection',
        context: {
          problemStatement,
          approach,
          wordCount,
        },
      }
    }

    return {
      shouldCallAI: false,
      reason: 'Idea does not meet quality threshold for reflection',
    }
  }

  /**
   * Decide whether to call AI for coding feedback
   */
  decideCodingFeedback(
    explanation: string | undefined,
    timeTaken: number | undefined,
    codeLength: number,
    challengeTitle?: string
  ): OrchestratorDecision {
    const ruleResult = evaluateCoding({
      explanation,
      timeTaken,
      codeLength,
    })

    // Rule: Only provide feedback if explanation exists
    if (ruleResult.shouldCallAI && explanation) {
      return {
        shouldCallAI: true,
        module: 'codingFeedback',
        reason: 'Submission has explanation suitable for feedback',
        context: {
          explanation,
          timeTaken,
          challengeTitle,
        },
      }
    }

    return {
      shouldCallAI: false,
      reason: 'Missing explanation or does not meet feedback criteria',
    }
  }

  /**
   * Decide whether to trigger weekly growth reflection
   */
  decideWeeklyGrowth(
    activityCountLast7Days: number,
    consistencyDetected: boolean
  ): OrchestratorDecision {
    // Rule: Only generate weekly reflection if there's meaningful activity
    if (activityCountLast7Days >= 3 || consistencyDetected) {
      return {
        shouldCallAI: true,
        module: 'weeklyGrowth',
        reason: 'Sufficient activity for weekly reflection',
        context: {
          activityCount: activityCountLast7Days,
          consistencyDetected,
        },
      }
    }

    return {
      shouldCallAI: false,
      reason: 'Insufficient activity for weekly reflection',
    }
  }

  /**
   * Execute AI call based on decision
   */
  async executeDecision(decision: OrchestratorDecision): Promise<string> {
    if (!decision.shouldCallAI || !decision.module) {
      throw new Error('Cannot execute: AI call not recommended')
    }

    const { module, context } = decision

    let prompt = ''
    let systemPrompt = SYSTEM_PROMPTS[module]

    switch (module) {
      case 'ideaGuidance':
        prompt = PROMPTS.ideaGuidance(
          context.problemStatement,
          context.approach
        )
        break

      case 'ideaReflection':
        prompt = PROMPTS.ideaReflection(
          context.problemStatement,
          context.approach,
          context.wordCount
        )
        break

      case 'codingFeedback':
        prompt = PROMPTS.codingFeedback(
          context.explanation,
          context.timeTaken,
          context.challengeTitle
        )
        break

      case 'weeklyGrowth':
        prompt = PROMPTS.weeklyGrowth(
          context.activitySummary || '',
          context.consistencyPattern || '',
          context.recentHighlights || ''
        )
        break

      default:
        throw new Error(`Unknown AI module: ${module}`)
    }

    const response = await this.aiService.call(prompt, systemPrompt)

    if (response.error) {
      throw new Error(`AI service error: ${response.error}`)
    }

    return response.content
  }
}

/**
 * Rule Engine - Pure Logic Layer (NO AI)
 * 
 * Evaluates user submissions based on objective metrics:
 * - Word count
 * - Submission frequency
 * - Time gaps
 * - Iteration patterns
 * - Consistency streaks
 */

export interface RuleEngineResult {
  shouldCallAI: boolean
  flags: string[]
  signals: {
    needsDepth?: boolean
    inactivityDetected?: boolean
    consistencyDetected?: boolean
    qualityThreshold?: boolean
  }
  metadata: Record<string, any>
}

export interface IdeaEvaluationInput {
  problemStatement: string
  approach: string
  wordCount?: number
}

export interface ActivityEvaluationInput {
  lastActivityDate?: Date
  submissionCountLast7Days: number
  submissionCountLast30Days: number
}

export interface CodingEvaluationInput {
  explanation?: string
  timeTaken?: number
  codeLength: number
}

/**
 * Evaluate idea submission quality
 */
export function evaluateIdea(input: IdeaEvaluationInput): RuleEngineResult {
  const problemWords = input.problemStatement?.split(/\s+/).length || 0
  const approachWords = input.approach?.split(/\s+/).length || 0
  const totalWords = input.wordCount || (problemWords + approachWords)

  const flags: string[] = []
  const signals: RuleEngineResult['signals'] = {}
  let shouldCallAI = false

  // Rule: Idea too short ΓåÆ flag "needs depth"
  if (totalWords < 150) {
    flags.push('needs_depth')
    signals.needsDepth = true
    shouldCallAI = false // Skip AI if too short
  } else if (totalWords < 300) {
    flags.push('could_be_deeper')
    signals.needsDepth = true
    shouldCallAI = true // Call AI for guidance
  } else {
    signals.qualityThreshold = true
    shouldCallAI = true // Call AI for reflection
  }

  // Rule: Check structure completeness
  if (!input.problemStatement || input.problemStatement.trim().length < 50) {
    flags.push('missing_problem_statement')
  }

  if (!input.approach || input.approach.trim().length < 50) {
    flags.push('missing_approach')
  }

  return {
    shouldCallAI,
    flags,
    signals,
    metadata: {
      wordCount: totalWords,
      problemWordCount: problemWords,
      approachWordCount: approachWords,
    },
  }
}

/**
 * Evaluate activity patterns
 */
export function evaluateActivity(input: ActivityEvaluationInput): RuleEngineResult {
  const flags: string[] = []
  const signals: RuleEngineResult['signals'] = {}
  let shouldCallAI = false

  // Rule: No activity for 7 days ΓåÆ inactivity signal
  if (input.lastActivityDate) {
    const daysSinceLastActivity = Math.floor(
      (Date.now() - input.lastActivityDate.getTime()) / (1000 * 60 * 60 * 24)
    )

    if (daysSinceLastActivity >= 7) {
      flags.push('inactivity_detected')
      signals.inactivityDetected = true
    }
  }

  // Rule: Daily submissions ΓåÆ consistency signal
  if (input.submissionCountLast7Days >= 5) {
    flags.push('consistency_detected')
    signals.consistencyDetected = true
    shouldCallAI = true // Good time for weekly reflection
  }

  // Rule: Low activity ΓåÆ flag
  if (input.submissionCountLast30Days < 3) {
    flags.push('low_activity')
  }

  return {
    shouldCallAI,
    flags,
    signals,
    metadata: {
      submissionCountLast7Days: input.submissionCountLast7Days,
      submissionCountLast30Days: input.submissionCountLast30Days,
    },
  }
}

/**
 * Evaluate coding submission
 */
export function evaluateCoding(input: CodingEvaluationInput): RuleEngineResult {
  const flags: string[] = []
  const signals: RuleEngineResult['signals'] = {}
  let shouldCallAI = false

  // Rule: Missing explanation ΓåÆ flag
  if (!input.explanation || input.explanation.trim().length < 20) {
    flags.push('missing_explanation')
  } else {
    shouldCallAI = true // Has explanation, can provide feedback
  }

  // Rule: Code too short might indicate incomplete attempt
  if (input.codeLength < 50) {
    flags.push('code_too_short')
  }

  // Rule: Time taken can indicate complexity
  if (input.timeTaken && input.timeTaken > 3600) {
    flags.push('long_time_taken') // Over 1 hour
  }

  return {
    shouldCallAI,
    flags,
    signals,
    metadata: {
      hasExplanation: !!input.explanation,
      explanationLength: input.explanation?.length || 0,
      codeLength: input.codeLength,
      timeTaken: input.timeTaken,
    },
  }
}

/**
 * Check if weekly reflection should be triggered
 */
export function shouldTriggerWeeklyReflection(
  lastWeeklyInsightDate: Date | null,
  activityCountLast7Days: number
): boolean {
  // If never generated, generate if there's activity
  if (!lastWeeklyInsightDate) {
    return activityCountLast7Days > 0
  }

  // If last generated more than 7 days ago and there's activity
  const daysSinceLastInsight = Math.floor(
    (Date.now() - lastWeeklyInsightDate.getTime()) / (1000 * 60 * 60 * 24)
  )

  return daysSinceLastInsight >= 7 && activityCountLast7Days > 0
}

import Credentials from "next-auth/providers/credentials"
import type { NextAuthOptions } from "next-auth"

// Simple in-memory user store for MVP (replace with database or Prisma later)
const users: Record<string, any> = {}

export const authOptions: NextAuthOptions = {
  secret: process.env.NEXTAUTH_SECRET || "evidya-secret-key-change-in-production",
  providers: [
    Credentials({
      id: "credentials",
      name: "Credentials",
      credentials: {
        email: { label: "Email", type: "email", placeholder: "email@example.com" },
        password: { label: "Password", type: "password" }
      },
      async authorize(credentials: any) {
        try {
          if (!credentials?.email || !credentials?.password) {
            return null
          }

          const user = users[credentials.email as string]
          if (user && user.password === credentials.password) {
            return {
              id: user.id,
              email: user.email,
              name: user.name,
            }
          }
          return null
        } catch (error) {
          console.error("Auth error:", error)
          return null
        }
      }
    })
  ],
  pages: {
    signIn: "/auth/signin",
  },
  callbacks: {
    async jwt({ token, user }: any) {
      if (user) {
        token.id = user.id
        token.email = user.email
      }
      return token
    },
    async session({ session, token }: any) {
      if (session.user) {
        ;(session.user as any).id = token.id
        session.user.email = token.email
      }
      return session
    },
  },
  session: {
    strategy: "jwt",
    maxAge: 30 * 24 * 60 * 60, // 30 days
  },
  events: {
    async signIn({ user }: any) {
      console.log("User signed in:", user?.email)
    },
  },
}

// Helper for server-side auth in API routes / server components
export async function getAuthSession() {
  const { getServerSession } = await import("next-auth/next")
  return getServerSession(authOptions)
}

// Export user creation function (in-memory for now)
export async function createUser(userData: {
  email: string
  name: string
  password: string
  college: string
  areaOfInterest: string
  shortGoal: string
}) {
  if (users[userData.email]) {
    throw new Error("User already exists")
  }
  users[userData.email] = {
    id: Math.random().toString(),
    email: userData.email,
    name: userData.name,
    password: userData.password, // Store password (in production, hash it!)
    college: userData.college,
    areaOfInterest: userData.areaOfInterest,
    shortGoal: userData.shortGoal
  }
  return users[userData.email]
}

import { PrismaClient } from '@prisma/client'

// Guard Prisma initialization: only construct PrismaClient when DATABASE_URL is present.
// This prevents server startup failures in demo/MVP mode when no DB is configured.
let client: any = undefined

if (process.env.DATABASE_URL) {
  const globalForPrisma = globalThis as unknown as { prisma: PrismaClient | undefined }
  client = globalForPrisma.prisma ?? new PrismaClient()
  if (process.env.NODE_ENV !== 'production') globalForPrisma.prisma = client
} else {
  // No DATABASE_URL: provide a throw-on-use proxy to avoid constructing PrismaClient.
  client = new Proxy({}, {
    get() {
      return () => {
        throw new Error('Prisma client is not initialized because DATABASE_URL is not set.')
      }
    }
  })
}

export const prisma: any = client
